import com.yjw.vultr.AccountState;
import org.json.*;
public class AccountStateTest {
 public static void main(String[] args)throws Exception{JSONObject raw=new JSONObject().put("balance","-18.42").put("pending_charges","2.36000001").put("name","private account name");JSONObject saved=AccountState.from(raw,1000);if(!saved.getString("balance").equals("-18.42"))throw new AssertionError("storage must retain the raw ledger; subtract pending only in derived wallet values");if(!saved.getString("pending").equals("2.36000001"))throw new AssertionError("precision lost");if(saved.has("name")||saved.length()!=3)throw new AssertionError("account cache contains unnecessary data");if(AccountState.fresh(null,1000)||AccountState.fresh(saved,301001)||AccountState.fresh(saved,999)||!AccountState.fresh(saved,301000))throw new AssertionError("cache freshness");for(JSONObject invalid:new JSONObject[]{new JSONObject(),new JSONObject().put("balance",0),new JSONObject().put("balance","invalid").put("pending_charges",0)}){boolean failed=false;try{AccountState.from(invalid,2000);}catch(Exception e){failed=true;}if(!failed)throw new AssertionError("unknown data became zero");}if(!saved.getString("balance").equals("-18.42")||saved.optLong("checked")!=1000)throw new AssertionError("failed refresh modified previous cache");for(String[] values:new String[][]{{"-100.55","60.25","40.30","0"},{"-23.47","13.48","9.99","0"},{"-10","12","0","2"},{"5","2","0","7"},{"0","0","0","0"},{"-10","-2","12","0"},{"-0.10","0.20","0","0.10"}}){JSONObject snapshot=AccountState.from(new JSONObject().put("balance",values[0]).put("pending_charges",values[1]),1000);if(AccountState.available(snapshot).compareTo(new java.math.BigDecimal(values[2]))!=0||AccountState.shortfall(snapshot).compareTo(new java.math.BigDecimal(values[3]))!=0)throw new AssertionError("wallet/shortfall: "+java.util.Arrays.toString(values));if(!snapshot.getString("balance").equals(new java.math.BigDecimal(values[0]).toPlainString()))throw new AssertionError("display conversion modified ledger cache");}
 if(AccountState.remaining(saved).compareTo(new java.math.BigDecimal("16.05999999"))!=0)throw new AssertionError("rounding before subtraction");
 System.out.println("PASS: available after pending, debt/zero/adjustments, balance sign, precision, minimal cache and expiration");}
}
